set local role authenticated;select pg_temp.claim(2);
select set_config('ga.review',public.group_command(null,'create',null,'{"offeringId":"60000000-0000-0000-0000-000000000001","name":"Review fixture","mode":"online","joinUrl":"https://meet.example.com/room","schedules":[{"weekday":2,"time":"18:00","durationMinutes":120},{"weekday":6,"time":"16:00","durationMinutes":120}]}')->>'id',true);
select set_config('ga.schedule_digest',(select md5(jsonb_agg(to_jsonb(r) order by r.id)::text) from public.group_schedules r where group_id=current_setting('ga.review')::uuid),true);
select set_config('ga.session_digest',(select md5(jsonb_agg(to_jsonb(r) order by r.id)::text) from public.group_sessions r where group_id=current_setting('ga.review')::uuid),true);
do $$declare patch jsonb;begin for patch in select value from jsonb_array_elements('[{"name":"Renamed"},{"description":"Updated notes"},{"capacity":50},{"location":"Room 4"},{"mode":"center"},{"instructions":"Bring notes"},{"joinUrl":"https://meet.example.com/new"}]'::jsonb) loop
 perform public.group_command(current_setting('ga.review')::uuid,'edit',(select version from public.study_groups where id=current_setting('ga.review')::uuid),patch);
end loop;end$$;
select pg_temp.ok((select md5(jsonb_agg(to_jsonb(r) order by r.id)::text)=current_setting('ga.schedule_digest') from public.group_schedules r where group_id=current_setting('ga.review')::uuid),'all metadata-only patches preserve recurrence templates');
select pg_temp.ok((select md5(jsonb_agg(to_jsonb(r) order by r.id)::text)=current_setting('ga.session_digest') from public.group_sessions r where group_id=current_setting('ga.review')::uuid),'metadata-only patches preserve session IDs snapshots and versions');
select public.group_command(current_setting('ga.review')::uuid,'edit',8,'{"schedules":[{"weekday":6,"time":"16:00","durationMinutes":120},{"weekday":2,"time":"18:00","durationMinutes":120}]}');
select pg_temp.ok((select md5(jsonb_agg(to_jsonb(r) order by r.id)::text)=current_setting('ga.schedule_digest') from public.group_schedules r where group_id=current_setting('ga.review')::uuid),'unchanged reordered schedules preserve template IDs and cursor');
select pg_temp.ok((select md5(jsonb_agg(to_jsonb(r) order by r.id)::text)=current_setting('ga.session_digest') from public.group_sessions r where group_id=current_setting('ga.review')::uuid),'unchanged schedules preserve every session');
select pg_temp.denied($q$select public.group_command(current_setting('ga.review')::uuid,'edit',8,'{"name":"Stale"}')$q$,'PT409','metadata patch stale version rejected');
select set_config('ga.retained_schedule',(select id::text from public.group_schedules where group_id=current_setting('ga.review')::uuid and active and weekday=2),true);
select set_config('ga.retained_sessions',(select md5(jsonb_agg(to_jsonb(r) order by r.id)::text) from public.group_sessions r where schedule_id=current_setting('ga.retained_schedule')::uuid),true);
select set_config('ga.review_exception',(select id::text from public.group_sessions where group_id=current_setting('ga.review')::uuid and schedule_id<>(current_setting('ga.retained_schedule')::uuid) order by starts_at limit 1),true);
select public.group_command(current_setting('ga.review')::uuid,'session',null,jsonb_build_object('sessionId',current_setting('ga.review_exception'),'sessionVersion',0,'operation','cancel','reason','Keep explicit cancellation'));
select public.group_command(current_setting('ga.review')::uuid,'edit',10,'{"schedules":[{"weekday":2,"time":"18:00","durationMinutes":120},{"weekday":6,"time":"16:00","durationMinutes":90}]}');
select pg_temp.ok(exists(select 1 from public.group_schedules where id=current_setting('ga.retained_schedule')::uuid and active),'delta edit retains unchanged weekly slot ID');
select pg_temp.ok((select md5(jsonb_agg(to_jsonb(r) order by r.id)::text)=current_setting('ga.retained_sessions') from public.group_sessions r where schedule_id=current_setting('ga.retained_schedule')::uuid),'delta edit retains unrelated stable session snapshots');
select pg_temp.ok((select cancelled and cancellation_reason='Keep explicit cancellation' from public.group_sessions where id=current_setting('ga.review_exception')::uuid),'delta edit preserves explicit cancellation');
select pg_temp.ok((select count(*)=2 from public.group_schedules where group_id=current_setting('ga.review')::uuid and active),'delta edit replaces only changed duration slot');
select public.group_command(current_setting('ga.review')::uuid,'edit',11,'{"schedules":[]}');
select pg_temp.ok(not exists(select 1 from public.group_schedules where group_id=current_setting('ga.review')::uuid and active),'explicit empty array clears recurrence deliberately');
select pg_temp.ok(not exists(select 1 from public.group_sessions where group_id=current_setting('ga.review')::uuid and starts_at>clock_timestamp() and not exception and not cancelled),'explicit empty array cancels generated future instances');
select pg_temp.ok((select cancellation_reason='Keep explicit cancellation' from public.group_sessions where id=current_setting('ga.review_exception')::uuid),'explicit clearing preserves exception');
select set_config('ga.cleared_digest',(select md5(jsonb_agg(to_jsonb(r) order by r.id)::text) from public.group_sessions r where group_id=current_setting('ga.review')::uuid),true);
select public.group_command(current_setting('ga.review')::uuid,'edit',12,'{"schedules":[]}');
select pg_temp.ok((select md5(jsonb_agg(to_jsonb(r) order by r.id)::text)=current_setting('ga.cleared_digest') from public.group_sessions r where group_id=current_setting('ga.review')::uuid),'repeated explicit clearing is session-idempotent');
-- These authenticated direct RPCs bypass all form/HTTP validation.
do $$declare bad text;begin foreach bad in array array['https://username:password@evil.example/video','https://not-a-domain','https://trusted.example@evil.example/video','https://bad..example','https://-bad.example','https://example.invalid:65536','https://example.invalid:0','https://example.invalid/ bad','https://example.invalid/%0d','https://example.invalid/%zz','https://127.0.0.1','https://[::1]','http://example.invalid',E'https://example.invalid/\tbad','https://example.invalid'||chr(92)||'evil.example'] loop
 perform pg_temp.denied(format('select public.group_command(null,''create'',null,%L::jsonb)',jsonb_build_object('offeringId','60000000-0000-0000-0000-000000000001','name','Rejected URL fixture','mode','online','joinUrl',bad)),'23514','direct URL rejected: '||bad);
 perform pg_temp.denied(format('select public.group_command(%L::uuid,''edit'',13,%L::jsonb)',current_setting('ga.review'),jsonb_build_object('joinUrl',bad)),'23514','direct URL edit rejected: '||bad);
end loop;end$$;
select public.group_command(current_setting('ga.review')::uuid,'edit',13,'{"joinUrl":"https://meet.example.com:8443/room?token=a%20b#join"}');
select pg_temp.ok((select join_url='https://meet.example.com:8443/room?token=a%20b#join' from public.study_groups where id=current_setting('ga.review')::uuid),'valid full URL query port and escaped space accepted');
select public.group_command(current_setting('ga.bulk')::uuid,'attendance',null,jsonb_build_object('sessionId',current_setting('ga.bulk_session'),'sessionVersion',0,'marks',jsonb_build_array(jsonb_build_object('userId',(select user_id from ga_bulk order by user_id limit 1),'status','attended'))));
reset role;
select pg_temp.ok((select jsonb_array_length(before_data->'marks')=1 from private.group_audit where session_id=current_setting('ga.bulk_session')::uuid and action='attendance' order by created_at desc limit 1),'single attendance edit copies one prior row not 28-person sheet');
select pg_temp.ok((select before_data->'marks'->0->>'status'='not_marked' and after_data->'input'->'marks'->0->>'status'='attended' from private.group_audit where session_id=current_setting('ga.bulk_session')::uuid and action='attendance' order by created_at desc limit 1),'compact audit retains exact old and requested new status');
select pg_temp.ok(exists(select 1 from private.group_audit where session_id=current_setting('ga.past')::uuid and action='finalize' and after_data->>'sheetDigest' ~ '^[0-9a-f]{64}$'),'finalization stores fixed-size SHA256 sheet evidence');
select pg_temp.denied(format('update public.group_sessions set join_url=%L where id=%L::uuid','https://trusted.example@evil.example/video',current_setting('ga.review_exception')),'23514','session snapshot URL constraint rejects privileged malformed value');
select pg_temp.ok(not exists(select 1 from public.study_groups where name='Rejected URL fixture'),'failed direct URL attempts persist no group');


select set_config('ga.attendance_digest',(select md5(jsonb_agg(to_jsonb(a) order by a.user_id)::text) from public.session_attendance a where session_id=current_setting('ga.bulk_session')::uuid),true);
select set_config('ga.attendance_session',(select to_jsonb(s)::text from public.group_sessions s where id=current_setting('ga.bulk_session')::uuid),true);
set local role authenticated;select pg_temp.claim(2);
select public.group_command(current_setting('ga.bulk')::uuid,'edit',(select version from public.study_groups where id=current_setting('ga.bulk')::uuid),'{"name":"Metadata retains attendance","description":"No recurrence supplied","capacity":100}');
reset role;
select pg_temp.ok((select md5(jsonb_agg(to_jsonb(a) order by a.user_id)::text)=current_setting('ga.attendance_digest') from public.session_attendance a where session_id=current_setting('ga.bulk_session')::uuid),'metadata edits retain exact existing attendance rows');
select pg_temp.ok((select to_jsonb(s)::text=current_setting('ga.attendance_session') from public.group_sessions s where id=current_setting('ga.bulk_session')::uuid),'metadata edits retain snapshotted attendance session unchanged');


select pg_temp.ok(not private.valid_group_meeting_url('https://example.invalid/'||chr(9)||'bad'),'URL checker rejects actual tab');
select pg_temp.ok(not private.valid_group_meeting_url('https://example.invalid/'||chr(10)||'bad'),'URL checker rejects actual newline');
select set_config('ga.past_auto',(select md5(jsonb_agg(to_jsonb(s) order by s.id)::text) from public.group_sessions s where group_id=current_setting('ga.catchup')::uuid and ends_at<clock_timestamp()),true);
set local role authenticated;select pg_temp.claim(2);
select public.group_command(current_setting('ga.catchup')::uuid,'edit',(select version from public.study_groups where id=current_setting('ga.catchup')::uuid),'{"schedules":[]}');
reset role;
select pg_temp.ok((select md5(jsonb_agg(to_jsonb(s) order by s.id)::text)=current_setting('ga.past_auto') from public.group_sessions s where group_id=current_setting('ga.catchup')::uuid and ends_at<clock_timestamp()),'explicit recurrence clearing preserves past automatic sessions');

select count(*) as groups_attendance_tests from ga_results;
rollback;
